function getQuillbotTranslation(key, lang) {
  if (quillbotTranslations[lang] && quillbotTranslations[lang][key]) {
    return quillbotTranslations[lang][key];
  }
  if (quillbotTranslations.en && quillbotTranslations.en[key]) {
    return quillbotTranslations.en[key];
  }
  return null;
}

function applyQuillbotTranslations(lang) {
  console.log(`🔥 Applying quillbot translations for: ${lang}`);
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.quillbot.') || key.startsWith('review.common.'))) {
      const translation = getQuillbotTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  console.log(`✅ Applied ${count} quillbot translations`);
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyQuillbotTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyQuillbotTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyQuillbotTranslations(currentLang);
}

console.log('✅ quillbot i18n loaded');
